import{_ as r,r as a,o,c as i,e as n,a as h,s as c}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Hashing & Encryption - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Configuration","slug":"configuration","link":"#configuration","children":[]},{"level":2,"title":"Hashing","slug":"hashing","link":"#hashing","children":[{"level":4,"title":"Verifying a password against a hash","slug":"verifying-a-password-against-a-hash","link":"#verifying-a-password-against-a-hash","children":[]},{"level":4,"title":"Checking if a password needs to be rehashed","slug":"checking-if-a-password-needs-to-be-rehashed","link":"#checking-if-a-password-needs-to-be-rehashed","children":[]}]},{"level":2,"title":"Encryption","slug":"encryption","link":"#encryption","children":[{"level":4,"title":"Decrypting a value","slug":"decrypting-a-value","link":"#decrypting-a-value","children":[]}]}],"relativePath":"1.x/services/hashing-encryption.md","filePath":"1.x/services/hashing-encryption.md"}'),d={name:"1.x/services/hashing-encryption.md"};function p(l,e,g,y,u,f){const t=a("pre-heading"),s=a("post-heading");return o(),i("div",null,[n(t),e[0]||(e[0]=h("h1",null,"Hashing & Encryption",-1)),n(s),e[1]||(e[1]=c(`<h2 id="configuration"><a href="#configuration" class="header-anchor">#</a> Configuration</h2><p>When you first installed October, a random key should have been generated for you. You can confirm this by checking the <code>key</code> option of your <code>config/app.php</code> configuration file. If the key remains unchanged, you should set it to a 32 character, random string. If this value is not properly set, all encrypted values will be insecure.</p><h2 id="hashing"><a href="#hashing" class="header-anchor">#</a> Hashing</h2><p>The <code>Hash</code> facade provides secure Bcrypt hashing for storing user passwords. Bcrypt is a great choice for hashing passwords because its &quot;work factor&quot; is adjustable, which means that the time it takes to generate a hash can be increased as hardware power increases.</p><p>You may hash a password by calling the <code>make</code> method on the <code>Hash</code> facade:</p><pre><code>$user = new User;
$user-&gt;password = Hash::make(&#39;mypassword&#39;);
$user-&gt;save();
</code></pre><p>Alternatively, models can implement the <a href="./../database/traits.html#hashable">Hashable trait</a> to automatically hash attributes.</p><h4 id="verifying-a-password-against-a-hash"><a href="#verifying-a-password-against-a-hash" class="header-anchor">#</a> Verifying a password against a hash</h4><p>The <code>check</code> method allows you to verify that a given plain-text string corresponds to a given hash.</p><pre><code>if (Hash::check(&#39;plain-text&#39;, $hashedPassword)) {
    // The passwords match...
}
</code></pre><h4 id="checking-if-a-password-needs-to-be-rehashed"><a href="#checking-if-a-password-needs-to-be-rehashed" class="header-anchor">#</a> Checking if a password needs to be rehashed</h4><p>The <code>needsRehash</code> function allows you to determine if the work factor used by the hasher has changed since the password was hashed:</p><pre><code>if (Hash::needsRehash($hashed)) {
    $hashed = Hash::make(&#39;plain-text&#39;);
}
</code></pre><h2 id="encryption"><a href="#encryption" class="header-anchor">#</a> Encryption</h2><p>You may encrypt a value using the <code>Crypt</code> facade. All encrypted values are encrypted using OpenSSL and the <code>AES-256-CBC</code> cipher. Furthermore, all encrypted values are signed with a message authentication code (MAC) to detect any modifications to the encrypted string.</p><p>For example, we may use the <code>encrypt</code> method to encrypt a secret and store it on a <a href="./../database/model.html">database model</a>:</p><pre><code>$user = new User;
$user-&gt;secret = Crypt::encrypt(&#39;shhh no telling&#39;);
$user-&gt;save();
</code></pre><h4 id="decrypting-a-value"><a href="#decrypting-a-value" class="header-anchor">#</a> Decrypting a value</h4><p>Of course, you may decrypt values using the <code>decrypt</code> method on the <code>Crypt</code> facade. If the value can not be properly decrypted, such as when the MAC is invalid, an <code>Illuminate\\Contracts\\Encryption\\DecryptException</code> exception will be thrown:</p><pre><code>use Illuminate\\Contracts\\Encryption\\DecryptException;

try {
    $decrypted = Crypt::decrypt($encryptedValue);
}
catch (DecryptException $ex) {
    //
}
</code></pre>`,20))])}const w=r(d,[["render",p]]);export{v as __pageData,w as default};
